def minimum_guess_budget(n):
    cost = [[0]*(n+2) for _ in range(n+2)]
    for width in range(2,n+1):
        for low in range(1,n-width+2):
            high = low+width-1
            cost[low][high] = min(guess+max(cost[low][guess-1],cost[guess+1][high])
                                  for guess in range(low,high+1))
    return cost[1][n]

